phase1.code:
fn main() {
    // ---- References allow borrowing without ownership ----
    let s1 = String::from("hello");
    let len = calculate_length(&s1);  // Borrow s1
    println!("The length of '{}' is {}.", s1, len);  // s1 still valid

    // ---- Mutable references ----
    let mut s2 = String::from("hello");
    change(&mut s2);  // Mutable borrow
    println!("s2: {}", s2);

    // ---- Multiple immutable references allowed ----
    let s3 = String::from("hello");
    let r1 = &s3;
    let r2 = &s3;
    println!("r1: {}, r2: {}", r1, r2);  // Both valid

    // ---- Mutable references: only one at a time ----
    let mut s4 = String::from("hello");
    let r3 = &mut s4;
    // let r4 = &mut s4;  // ERROR! Cannot borrow as mutable more than once
    // println!("{}", r3);

    // ---- Cannot have mutable and immutable references together ----
    let mut s5 = String::from("hello");
    let r5 = &s5;
    let r6 = &s5;
    // let r7 = &mut s5;  // ERROR! Cannot borrow as mutable when immutable borrows exist
    println!("r5: {}, r6: {}", r5, r6);

    // ---- Reference scoping ----
    let mut s6 = String::from("hello");
    {
        let r8 = &mut s6;  // Mutable borrow starts here
        r8.push_str(" world");
    }  // Mutable borrow ends here
    let r9 = &s6;  // Immutable borrow allowed after mutable borrow ends
    println!("r9: {}", r9);
}

fn calculate_length(s: &String) -> usize {
    s.len()  // Borrow, not own
}

fn change(s: &mut String) {
    s.push_str(", world");  // Mutate through mutable reference
}

